def render_template(template, context):
    if not isinstance(template, str):
        raise TypeError("template must be a string")
    if not isinstance(context, dict):
        raise TypeError("context must be a dict")

    name_chars = "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_"
    out = []
    n = len(template)
    i = 0
    while i < n:
        ch = template[i]
        if ch == "{":
            # Escape "{{" wins over placeholder interpretation.
            if i + 1 < n and template[i + 1] == "{":
                out.append("{")
                i += 2
                continue
            p = i
            j = i + 1
            while True:
                if j >= n:
                    raise ValueError(f"unclosed placeholder at position {p}")
                c = template[j]
                if c == "}":
                    if j == i + 1:
                        raise ValueError(f"empty placeholder at position {p}")
                    break
                if c not in name_chars:
                    raise ValueError(f"invalid placeholder at position {p}")
                j += 1
            name = template[i + 1:j]
            out.append(str(context[name]))  # missing key -> KeyError(name)
            i = j + 1
        elif ch == "}":
            # Escape "}}" wins over stray-brace interpretation.
            if i + 1 < n and template[i + 1] == "}":
                out.append("}")
                i += 2
                continue
            raise ValueError(f"stray '}}' at position {i}")
        else:
            out.append(ch)
            i += 1
    return "".join(out)

def eval_rpn(tokens):
    if not isinstance(tokens, list):
        raise TypeError("tokens must be a list")
    if len(tokens) == 0:
        raise ValueError("empty expression")

    stack = []
    operators = ("+", "-", "*", "/")

    for i, token in enumerate(tokens):
        if not isinstance(token, str):
            raise TypeError(f"token {i} is not a string")

        if token in operators:
            if len(stack) < 2:
                raise ValueError(f"stack underflow at token {i}")
            right = stack.pop()
            left = stack.pop()
            if token == "+":
                stack.append(left + right)
            elif token == "-":
                stack.append(left - right)
            elif token == "*":
                stack.append(left * right)
            else:  # "/"
                if right == 0:
                    raise ZeroDivisionError(f"division by zero at token {i}")
                # Truncation toward zero (C-style), exact for big ints.
                quotient = abs(left) // abs(right)
                if (left < 0) != (right < 0):
                    quotient = -quotient
                stack.append(quotient)
        else:
            # Validate: optional single sign, then one or more ASCII digits.
            body = token
            if body[:1] == "+" or body[:1] == "-":
                body = body[1:]
            if len(body) == 0:
                raise ValueError(f"unknown token {i}")
            value = 0
            for ch in body:
                if not ("0" <= ch <= "9"):
                    raise ValueError(f"unknown token {i}")
                # Manual accumulation avoids int()'s string-length cap,
                # keeping arbitrarily large literals exact.
                value = value * 10 + (ord(ch) - 48)
            if token[0] == "-":
                value = -value
            stack.append(value)

    if len(stack) > 1:
        raise ValueError("leftover operands")
    return stack[0]

def flatten_depth(nested, max_depth):
    if not isinstance(nested, list):
        raise TypeError("nested must be a list")
    if isinstance(max_depth, bool) or not isinstance(max_depth, int):
        raise TypeError("max_depth must be an int")
    if max_depth < 0:
        raise ValueError("max_depth must be >= 0")

    flattened = []
    stack = [(iter(nested), 0)]

    while stack:
        iterator, depth = stack[-1]
        try:
            item = next(iterator)
        except StopIteration:
            stack.pop()
            continue

        if type(item) is list and depth < max_depth:
            stack.append((iter(item), depth + 1))
        else:
            flattened.append(item)

    return flattened

def deep_get(data, path):
    if not isinstance(path, str):
        raise TypeError("path must be a string")
    if path == "":
        raise ValueError("path must not be empty")

    segments = path.split(".")

    def reject_empty(remaining):
        if not remaining:
            return
        if remaining[0] == "":
            raise ValueError("empty segment in path")
        reject_empty(remaining[1:])

    def parse_index(segment):
        digits = segment[1:] if segment.startswith("-") else segment
        if digits == "" or not (digits.isascii() and digits.isdigit()):
            raise ValueError("invalid index: " + segment)
        return int(segment)

    def descend(node, remaining):
        if not remaining:
            return node
        segment = remaining[0]
        rest = remaining[1:]
        if isinstance(node, dict):
            if segment not in node:
                raise KeyError(segment)
            return descend(node[segment], rest)
        if isinstance(node, list):
            index = parse_index(segment)
            if index >= len(node) or index < -len(node):
                raise IndexError("index " + segment + " out of range")
            return descend(node[index], rest)
        raise TypeError("cannot descend into " + type(node).__name__)

    reject_empty(segments)
    return descend(data, segments)

def summarize_by_category(rows):
    if not isinstance(rows, list):
        raise TypeError("rows must be a list")

    summaries = {}

    for i, row in enumerate(rows):
        # a. must be a tuple of exactly 3 elements
        if not isinstance(row, tuple) or len(row) != 3:
            raise TypeError(
                f"row {i} must be a tuple of exactly 3 elements"
            )

        category, amount, refunded = row

        # b. category must be a non-empty str
        if not isinstance(category, str) or not category:
            raise ValueError(
                f"row {i} category must be a non-empty str"
            )

        # c. amount must be int or float, but not bool
        if isinstance(amount, bool) or not isinstance(amount, (int, float)):
            raise TypeError(
                f"row {i} amount must be an int or float (not bool)"
            )

        # d. amount must be >= 0
        if amount < 0:
            raise ValueError(f"row {i} amount must be >= 0")

        # e. refunded must be a bool
        if not isinstance(refunded, bool):
            raise TypeError(f"row {i} refunded must be a bool")

        amount_f = float(amount)

        summary = summaries.get(category)
        if summary is None:
            summaries[category] = {
                "count": 1,
                "gross": amount_f,
                "net": 0.0 if refunded else amount_f,
                "largest": amount_f,
            }
        else:
            summary["count"] += 1
            summary["gross"] += amount_f
            if not refunded:
                summary["net"] += amount_f
            if amount_f > summary["largest"]:
                summary["largest"] = amount_f

    return summaries

def top_k_frequent(items, k):
    if not isinstance(items, list):
        raise TypeError("items must be a list")
    if isinstance(k, bool) or not isinstance(k, int):
        raise TypeError("k must be an int")
    if k < 0:
        raise ValueError("k must be >= 0")
    counts = {}
    order = []
    for value in items:
        if value in counts:
            counts[value] = counts[value] + 1
        else:
            counts[value] = 1
            order.append(value)
    pairs = []
    for value in order:
        pairs.append((value, counts[value]))
    result = []
    while len(result) < k and pairs:
        best = 0
        i = 1
        while i < len(pairs):
            if pairs[i][1] > pairs[best][1]:
                best = i
            i = i + 1
        result.append(pairs.pop(best))
    return result

def clamp_values(values, low, high):
    if not isinstance(values, list):
        raise TypeError("values must be a list")
    if isinstance(low, bool) or not isinstance(low, (int, float)):
        raise TypeError("bounds must be numbers")
    if isinstance(high, bool) or not isinstance(high, (int, float)):
        raise TypeError("bounds must be numbers")
    if low > high:
        raise ValueError("low must not exceed high")

    result = []
    for i, value in enumerate(values):
        if isinstance(value, bool) or not isinstance(value, (int, float)):
            raise TypeError("index " + str(i))
        if value < low:
            result.append(low)
        elif value > high:
            result.append(high)
        else:
            result.append(value)
    return result

def parse_duration(text):
    if not isinstance(text, str):
        raise TypeError("expected str")
    if not text.strip():
        raise ValueError("empty duration")

    units = {"h": (0, 3600), "m": (1, 60), "s": (2, 1)}
    i = 0
    n = len(text)
    last_order = -1
    total = 0

    while i < n:
        ch = text[i]
        if ch < "0" or ch > "9":
            raise ValueError("malformed duration")

        value = 0
        while i < n:
            ch = text[i]
            if ch < "0" or ch > "9":
                break
            value = value * 10 + (ord(ch) - ord("0"))
            i += 1

        if i == n:
            raise ValueError("malformed duration")

        info = units.get(text[i])
        if info is None:
            raise ValueError("malformed duration")

        order, multiplier = info
        if order <= last_order:
            raise ValueError("malformed duration")

        last_order = order
        total += value * multiplier
        i += 1

    return total

from collections import deque

def round_robin(iterables: list) -> "iterator":
    pending = deque(iter(it) for it in iterables)
    while pending:
        it = pending.popleft()
        try:
            value = next(it)
        except StopIteration:
            continue
        yield value
        pending.append(it)

