def count_stable_windows(readings: list[int], tol: int) -> int:
    max_indices = deque()
    min_indices = deque()
    left = 0
    count = 0

    for right, value in enumerate(readings):
        while max_indices and readings[max_indices[-1]] <= value:
            max_indices.pop()
        max_indices.append(right)

        while min_indices and readings[min_indices[-1]] >= value:
            min_indices.pop()
        min_indices.append(right)

        while readings[max_indices[0]] - readings[min_indices[0]] > tol:
            if max_indices[0] == left:
                max_indices.popleft()
            if min_indices[0] == left:
                min_indices.popleft()
            left += 1

        count += right - left + 1

    return count

def rank_scores(scores: list) -> list[int]:
    # NaN is the only value not equal to itself.
    for s in scores:
        if s != s:
            raise ValueError("scores must not contain NaN")

    # Map each distinct score to its competition rank ("1224" ranking).
    # set() treats -0.0 == 0.0 and 2 == 2.0 as the same key.
    distinct = sorted(set(scores), reverse=True)
    rank_of = {score: index + 1 for index, score in enumerate(distinct)}

    return [rank_of[s] for s in scores]

class Leaderboard:
    def __init__(self):
        # player -> (best_score, sequence_number_of_the_improving_submission)
        self._entries = {}
        self._clock = 0

    def submit(self, player, score) -> bool:
        self._clock += 1
        entry = self._entries.get(player)
        if entry is None or score > entry[0]:
            self._entries[player] = (score, self._clock)
            return True
        # No improvement: change nothing (timestamp untouched).
        return False

    def best(self, player) -> int:
        return self._entries[player][0]  # KeyError if unknown

    def rank(self, player) -> int:
        score = self._entries[player][0]  # KeyError if unknown
        return 1 + sum(1 for best, _ in self._entries.values() if best > score)

    def top(self, k) -> list:
        if k < 0:
            raise ValueError("k must be non-negative")
        ordered = sorted(
            self._entries.items(),
            key=lambda item: (-item[1][0], item[1][1]),
        )
        return [(player, best) for player, (best, _) in ordered[:k]]

    def player_count(self) -> int:
        return len(self._entries)

from heapq import heappop, heappush

def min_steps(grid, c):
    rows = len(grid)
    cols = len(grid[0])

    if grid[0][0] == -1 or grid[rows - 1][cols - 1] == -1:
        return -1

    n = rows * cols
    labels = [-1] * n
    cells_by_label = {}

    for r, row in enumerate(grid):
        base = r * cols
        for col, label in enumerate(row):
            i = base + col
            labels[i] = label
            if label != -1:
                cells_by_label.setdefault(label, []).append(i)

    # States [0, n): teleport unused.
    # States [n, 2*n): teleport used.
    # Each remaining state is a per-label hub. A teleport i -> j is represented
    # as (i, unused) --0--> hub(label) --c--> (j, used).
    inf = 10**30
    dist = [inf] * (2 * n)
    hub_for_label = {}
    hub_labels = []

    for label, cells in cells_by_label.items():
        if len(cells) > 1:
            hub_for_label[label] = len(dist)
            hub_labels.append(label)
            dist.append(inf)

    start = 0
    target = n - 1
    two_n = 2 * n

    dist[start] = 0
    heap = [(0, start)]

    while heap:
        d, u = heappop(heap)
        if d != dist[u]:
            continue

        if u == target or u == n + target:
            return d

        # Label hub: teleport to any cell with this label, entering the used layer.
        if u >= two_n:
            label = hub_labels[u - two_n]
            nd = d + c
            for i in cells_by_label[label]:
                v = n + i
                if nd < dist[v]:
                    dist[v] = nd
                    heappush(heap, (nd, v))
            continue

        if u < n:
            i = u
            layer_offset = 0

            hub = hub_for_label.get(labels[i])
            if hub is not None and d < dist[hub]:
                dist[hub] = d
                heappush(heap, (d, hub))
        else:
            i = u - n
            layer_offset = n

        r, col = divmod(i, cols)
        nd = d + 1

        if r > 0:
            j = i - cols
            if labels[j] != -1:
                v = layer_offset + j
                if nd < dist[v]:
                    dist[v] = nd
                    heappush(heap, (nd, v))

        if r + 1 < rows:
            j = i + cols
            if labels[j] != -1:
                v = layer_offset + j
                if nd < dist[v]:
                    dist[v] = nd
                    heappush(heap, (nd, v))

        if col > 0:
            j = i - 1
            if labels[j] != -1:
                v = layer_offset + j
                if nd < dist[v]:
                    dist[v] = nd
                    heappush(heap, (nd, v))

        if col + 1 < cols:
            j = i + 1
            if labels[j] != -1:
                v = layer_offset + j
                if nd < dist[v]:
                    dist[v] = nd
                    heappush(heap, (nd, v))

    return -1

from collections import OrderedDict


class TTLCache:
    """Fixed-capacity LRU cache with per-entry TTLs on an explicit logical clock."""

    def __init__(self, capacity):
        if not isinstance(capacity, int) or isinstance(capacity, bool) or capacity < 1:
            raise ValueError("capacity must be an integer >= 1")
        self.capacity = capacity
        # key -> (value, stored_time, ttl); OrderedDict order is LRU -> MRU.
        self._data = OrderedDict()
        self._hits = 0
        self._misses = 0
        self._evictions = 0
        self._expirations = 0

    def _purge(self, now):
        """Remove every entry that is dead at `now` (dead when now >= t + ttl)."""
        dead = [
            key
            for key, (_, stored_time, ttl) in self._data.items()
            if ttl is not None and now >= stored_time + ttl
        ]
        for key in dead:
            del self._data[key]
            self._expirations += 1

    def put(self, key, value, now, ttl=None):
        if ttl is not None and ttl <= 0:
            raise ValueError("ttl must be a positive number or None")
        self._purge(now)
        if key in self._data:
            # Update in place: refresh value, time, ttl, and recency. Never an eviction.
            self._data[key] = (value, now, ttl)
            self._data.move_to_end(key)
        else:
            if len(self._data) >= self.capacity:
                self._data.popitem(last=False)  # evict least-recently-used
                self._evictions += 1
            self._data[key] = (value, now, ttl)

    def get(self, key, now):
        self._purge(now)
        if key in self._data:
            self._hits += 1
            self._data.move_to_end(key)
            return self._data[key][0]
        self._misses += 1
        return None

    def stats(self):
        return {
            "hits": self._hits,
            "misses": self._misses,
            "evictions": self._evictions,
            "expirations": self._expirations,
        }

    def __len__(self):
        # No purging here: expired-but-not-yet-purged entries still count.
        return len(self._data)

def compute_balances(transactions):
    balances = {}
    for tx in transactions:
        amount = tx["amount"]
        if not isinstance(amount, str):
            raise ValueError("invalid amount")

        whole, dot, frac = amount.partition(".")
        if dot:
            valid = (
                whole != ""
                and frac != ""
                and len(frac) <= 2
                and all("0" <= ch <= "9" for ch in whole)
                and all("0" <= ch <= "9" for ch in frac)
            )
        else:
            valid = whole != "" and all("0" <= ch <= "9" for ch in whole)
        if not valid:
            raise ValueError("invalid amount")

        cents = 0
        for ch in whole:
            cents = cents * 10 + (ord(ch) - ord("0"))
        cents *= 100
        if frac:
            cents += (ord(frac[0]) - ord("0")) * 10
            if len(frac) == 2:
                cents += ord(frac[1]) - ord("0")

        if cents <= 0:
            raise ValueError("amount must be positive")

        sender = tx["from"]
        receiver = tx["to"]
        balances[sender] = balances.get(sender, 0) - cents
        balances[receiver] = balances.get(receiver, 0) + cents
    return balances

class UndoStack:
    """A LIFO stack whose mutating operations (push/pop) can be undone."""

    _PUSH = "push"
    _POP = "pop"

    def __init__(self):
        self._items = []
        self._history = []

    def push(self, x) -> None:
        self._items.append(x)
        self._history.append((self._PUSH, None))

    def pop(self):
        if not self._items:
            raise IndexError("pop from empty UndoStack")
        value = self._items.pop()
        self._history.append((self._POP, value))
        return value

    def peek(self):
        if not self._items:
            raise IndexError("peek at empty UndoStack")
        return self._items[-1]

    def undo(self) -> None:
        if not self._history:
            raise RuntimeError("nothing to undo")
        op, value = self._history.pop()
        if op == self._PUSH:
            self._items.pop()
        else:  # undo a pop: put the exact popped value back on top
            self._items.append(value)

    def __len__(self) -> int:
        return len(self._items)

def resolve_build_order(deps):
    graph = {}
    for pkg, ds in deps.items():
        graph.setdefault(pkg, [])
        for d in ds:
            graph.setdefault(d, [])
            graph[pkg].append(d)
    order = []
    visiting = set()  # nodes on the current DFS path (gray)
    done = set()      # nodes fully processed (black)

    def visit(node):
        if node in done:
            return
        if node in visiting:
            raise ValueError("dependency cycle detected at " + node)
        visiting.add(node)
        for dep in sorted(set(graph[node])):
            visit(dep)
        visiting.remove(node)
        done.add(node)
        order.append(node)

    for node in sorted(graph):
        if node not in done:
            visit(node)
    return order

def apply_hunks(lines, hunks):
    ordered = sorted(hunks, key=lambda h: h[0])
    for i in range(1, len(ordered)):
        prev = ordered[i - 1]
        if ordered[i][0] == prev[0] or ordered[i][0] < prev[0] + prev[1]:
            raise ValueError("conflicting hunks")
    for start, delete, insert in ordered:
        if start < 0 or start + delete > len(lines):
            raise ValueError("hunk out of range")
    result = list(lines)
    for start, delete, insert in reversed(ordered):
        result[start:start + delete] = list(insert)
    return result

def smallest_balanced(s: str) -> str:
    n = len(s)
    if n & 1:
        raise ValueError

    fixed_open = s.count("(")
    wild = s.count("?")
    open_left = n // 2 - fixed_open
    if open_left < 0 or open_left > wild:
        raise ValueError

    out = []
    depth = 0
    for ch in s:
        if ch == "?":
            if open_left:
                ch = "("
                open_left -= 1
            else:
                ch = ")"

        if ch == "(":
            depth += 1
        elif ch == ")":
            depth -= 1
            if depth < 0:
                raise ValueError
        else:
            raise ValueError
        out.append(ch)

    if depth:
        raise ValueError
    return "".join(out)

def insert_booking(bookings, new):
    start, end = new
    if start >= end:
        raise ValueError("empty booking")
    result = []
    i = 0
    while i < len(bookings) and bookings[i][1] <= start:
        result.append(bookings[i])
        i += 1
    while i < len(bookings) and bookings[i][0] < end:
        start = min(start, bookings[i][0])
        end = max(end, bookings[i][1])
        i += 1
    result.append((start, end))
    result.extend(bookings[i:])
    return result

def purge_expired(sessions, now):
    purged = []
    for sid, expiry in list(sessions.items()):
        if expiry <= now:
            del sessions[sid]
            purged.append(sid)
    return purged

def merge_settings(defaults, overrides):
    result = dict(defaults)
    for key, value in overrides.items():
        if isinstance(value, dict) and isinstance(result.get(key), dict):
            result[key] = merge_settings(result[key], value)
        else:
            result[key] = value
    return result

class RateLimiter:
    def __init__(self, max_calls, window_seconds):
        self.max_calls = max_calls
        self.window = window_seconds
        self.calls = []

    def allow(self, timestamp):
        self.calls = [t for t in self.calls if timestamp - t < self.window]
        if len(self.calls) < self.max_calls:
            self.calls.append(timestamp)
            return True
        return False

def max_sessions(intervals, gap):
    """Return the maximum number of non-overlapping sessions selectable
    with at least `gap` idle time between consecutive sessions."""
    count = 0
    next_allowed = float("-inf")

    for start, end in sorted(intervals, key=lambda interval: interval[1]):
        if start >= next_allowed:
            count += 1
            next_allowed = end + gap

    return count
